struct Policy { double oxidative=0,injury=0,inflammation=0,recruitment=0,edema=0,death=0,repair=0,ecm=0,uptake=0,motility=0; };
static std::map<int,std::string> worker_by_cell;
static std::map<int,std::string> agent_by_cell;
static std::map<std::string,std::map<std::string,Policy>> policies;
static std::map<std::string,double> secretion_multiplier,uptake_multiplier,motility_multiplier,death_tendency,repair_tendency;
