std::vector<std::string> split(const std::string& s){std::vector<std::string> z;std::stringstream ss(s);std::string x;while(std::getline(ss,x,','))z.push_back(x);return z;}
int density(const std::string& x){return microenvironment.find_density_index(x);}
double clamp01(double x){return std::max(0.0,std::min(1.0,x));}
double hill_gate(double x,double threshold,double hill){if(x<=0)return 0.0;double xn=std::pow(x,hill),tn=std::pow(std::max(1e-6,threshold),hill);return xn/(xn+tn);}
bool contains(const std::string& x,const std::string& y){return x.find(y)!=std::string::npos;}

void load_policies(){}
std::string stage_name(Cell* c,double tox){
 double dm=c->custom_data["damage_memory"],im=c->custom_data["inflammatory_memory"],rm=c->custom_data["resolution_memory"],dur=c->custom_data["sustained_injury_duration"],inj=c->custom_data["injury_state"],ce=c->custom_data["cumulative_exposure"];
 int previous=(int)std::round(c->custom_data["stage_code"]);bool post=c->custom_data["post_exposure"]>.5;
 const double injury_on=.08,injury_off=.035,inflammatory_on=.04,inflammatory_off=.02,resolution_on=.025,resolution_off=.0125;
 bool all_off=dm<injury_off&&im<inflammatory_off&&rm<resolution_off&&ce<.03;
 bool resolution_ready=post&&tox<.03&&ce<.05&&dm>=.03&&rm>=resolution_on;
 int next=0,reason=0;
 if(resolution_ready){next=3;reason=1;}
 else if(previous==3&&(rm>=resolution_off||dm>=injury_off||im>=inflammatory_off)){next=3;reason=2;}
 else if(im>=inflammatory_on||(dur>=90&&inj>=.04)){next=2;reason=3;}
 else if(previous==2&&(im>=inflammatory_off||dm>=injury_off)){next=2;reason=4;}
 else if(dm>=injury_on||ce>=.06){next=1;reason=5;}
 else if(previous==1&&(dm>=injury_off||ce>=.03)){next=1;reason=6;}
 else if(all_off){next=0;reason=7;}
 else {next=previous==0?0:previous;reason=8;}
 c->custom_data["previous_stage_code"]=previous;c->custom_data["transition_reason_code"]=reason;
 return next==0?"early_stress":(next==1?"injury_accumulating":(next==2?"inflammatory":"resolution"));}
std::string transition_reason_name(int x){const char* names[9]={"initial_or_early","resolution_on","resolution_hysteresis","inflammatory_on","inflammatory_hysteresis","injury_on","injury_hysteresis","all_memories_off","retain_non_early_state"};return x>=0&&x<9?names[x]:"invalid_reason";}
Policy active(const std::string& agent,const std::string& stage){if(!policies.count(agent)||!policies[agent].count("online")){std::cerr<<"Missing online action "<<agent<<"\n";exit(32);}return policies[agent]["online"];}
void initialize_exposure(){int tox=density("toxicant_proxy");if(tox<0)return;bool injury=condition_name=="virtual_phosgene_injury";for(int n=0;n<microenvironment.number_of_voxels();n++){auto c=microenvironment.mesh.voxels[n].center;double r2=c[0]*c[0]+c[1]*c[1];microenvironment.density_vector(n)[tox]=injury?std::exp(-r2/(2.0*260.0*260.0)):0.0;}}

void emit(int minute){
  if(emitted.count(minute))return;emitted.insert(minute);
  std::ofstream w((run_out+"/work_cells_minute_"+std::to_string(minute)+".csv").c_str());w<<std::setprecision(12);
  w<<"minute,cell_id,worker_id,agent_id,x,y,represented_abundance,injury_state,inflammation_state,repair_state,cumulative_exposure,damage_memory,sustained_injury_duration,inflammatory_memory,resolution_memory,previous_stage,current_stage,transition_reason,exposure_peak,post_exposure,stage_code,toxicant_proxy,oxidative_stress,epithelial_injury,inflammation,edema_proxy,death_signal,repair_signal,REAL_PHYSICELL_USED,AGENT_POLICY_APPLIED\n";
  for(auto c:*all_cells){std::string a=agent_by_cell[c->ID];int checkpoint=minute>=480?480:(minute>=240?240:(minute>=60?60:(minute>=30?30:0)));auto d=c->nearest_density_vector();w<<minute<<","<<c->ID<<","<<worker_by_cell[c->ID]<<","<<a<<","<<c->position[0]<<","<<c->position[1]<<","<<c->custom_data["represented_abundance"]<<","<<c->custom_data["injury_state"]<<","<<c->custom_data["inflammation_state"]<<","<<c->custom_data["repair_state"]<<","<<c->custom_data["cumulative_exposure"]<<","<<c->custom_data["damage_memory"]<<","<<c->custom_data["sustained_injury_duration"]<<","<<c->custom_data["inflammatory_memory"]<<","<<c->custom_data["resolution_memory"]<<","<<c->custom_data["previous_stage_code"]<<","<<c->custom_data["stage_code"]<<","<<transition_reason_name((int)std::round(c->custom_data["transition_reason_code"]))<<","<<c->custom_data["exposure_peak"]<<","<<c->custom_data["post_exposure"]<<","<<c->custom_data["stage_code"];const char* names[7]={"toxicant_proxy","oxidative_stress","epithelial_injury","inflammation","edema_proxy","death_signal","repair_signal"};for(int j=0;j<7;j++)w<<","<<d[density(names[j])];w<<",true,true\n";}
  std::ofstream m((run_out+"/substrates_minute_"+std::to_string(minute)+".csv").c_str());m<<std::setprecision(12)<<"minute,voxel_id,x,y,toxicant_proxy,oxidative_stress,epithelial_injury,inflammation,edema_proxy,death_signal,repair_signal\n";const char* names[7]={"toxicant_proxy","oxidative_stress","epithelial_injury","inflammation","edema_proxy","death_signal","repair_signal"};for(int n=0;n<microenvironment.number_of_voxels();n++){auto c=microenvironment.mesh.voxels[n].center;m<<minute<<","<<n<<","<<c[0]<<","<<c[1];for(int j=0;j<7;j++)m<<","<<microenvironment.density_vector(n)[density(names[j])];m<<"\n";}
  std::ofstream s((run_out+"/source_terms_minute_"+std::to_string(minute)+".csv").c_str());s<<std::setprecision(12)<<"minute,field,mesh_mean,mesh_max,total_gross_source,mean_worker_gross_source,max_worker_gross_source\n";
  for(int j=0;j<7;j++){int id=density(names[j]);double mesh_sum=0,mesh_max=0,total=0,max_worker=0;for(int n=0;n<microenvironment.number_of_voxels();n++){double value=microenvironment.density_vector(n)[id];mesh_sum+=value;mesh_max=std::max(mesh_max,value);}for(auto c:*all_cells){auto d=c->nearest_density_vector();double gross=c->phenotype.volume.total*c->phenotype.secretion.secretion_rates[id]*std::max(0.0,c->phenotype.secretion.saturation_densities[id]-d[id]);total+=gross;max_worker=std::max(max_worker,gross);}s<<minute<<","<<names[j]<<","<<mesh_sum/microenvironment.number_of_voxels()<<","<<mesh_max<<","<<total<<","<<total/std::max(1,(int)all_cells->size())<<","<<max_worker<<"\n";}
}
void emit_due(){int steps[9]={0,30,60,240,480,720,1440,2880,4320};for(int k=0;k<9;k++)if(PhysiCell_globals.current_time+1e-7>=steps[k])emit(steps[k]);}
std::string slurp(const std::string& p){std::ifstream f(p.c_str());std::stringstream s;s<<f.rdbuf();return s.str();}
std::string file_sha256(const std::string& p){std::string cmd="sha256sum \""+p+"\"";FILE* f=popen(cmd.c_str(),"r");char b[80]={0};if(!f||!fgets(b,80,f)){if(f)pclose(f);return "hash_error";}pclose(f);return std::string(b).substr(0,64);}
double json_num(const std::string& s,const std::string& key,size_t start){size_t p=s.find("\""+key+"\"",start);if(p==std::string::npos){std::cerr<<"Missing response number "<<key<<"\n";exit(46);}p=s.find(':',p);double v=atof(s.c_str()+p+1);if(!std::isfinite(v)||v<0||v>1){std::cerr<<"Invalid response number "<<key<<"\n";exit(47);}return v;}
std::string json_str(const std::string& s,const std::string& key,size_t start=0){size_t p=s.find("\""+key+"\"",start);if(p==std::string::npos)return "";p=s.find(':',p);p=s.find('"',p);size_t q=s.find('"',p+1);return s.substr(p+1,q-p-1);}
void apply_abundance_requests(){for(auto const& z:abundance_fraction){std::string src=z.first,dst=abundance_target[src];double f=z.second;if(dst=="none"||f<=0)continue;double sw=0,dw=0;for(auto c:*all_cells){if(agent_by_cell[c->ID]==src)sw+=c->custom_data["represented_abundance"];if(agent_by_cell[c->ID]==dst)dw+=c->custom_data["represented_abundance"];}if(sw<=0||dw<=0)continue;double moved=std::min(f,sw);for(auto c:*all_cells){std::string a=agent_by_cell[c->ID];double &w=c->custom_data["represented_abundance"];if(a==src)w*=1-moved/sw;else if(a==dst)w+=moved*w/dw;}}double total=0;for(auto c:*all_cells)total+=c->custom_data["represented_abundance"];for(auto c:*all_cells)c->custom_data["represented_abundance"]/=total;}
void online_checkpoint(int minute){if(online_checkpoints_done.count(minute))return;online_checkpoints_done.insert(minute);emit(minute);std::string rid=run_out.substr(run_out.find_last_of('/')+1);int expected_seed=atoi(rid.c_str()+rid.find("seed_")+5);std::string root=run_out+"/runtime_responses/"+rid+"/"+std::to_string(minute);std::string mock=getenv("V4_MOCK_PROFILE")?std::string(" --mock-profile ")+getenv("V4_MOCK_PROFILE"):"";std::string timeout=getenv("V4_ONLINE_TIMEOUT_SECONDS")?getenv("V4_ONLINE_TIMEOUT_SECONDS"):"600";const char* bridge_env=getenv("V4_RUNTIME_BRIDGE_PATH");if(!bridge_env){std::cerr<<"V4_RUNTIME_BRIDGE_PATH is required\n";exit(43);}std::string script=bridge_env;std::string cmd="timeout "+timeout+"s python \""+script+"\" --run-dir \""+run_out+"\" --minute "+std::to_string(minute)+mock;std::string response_path=root+"/execution_payload.json";remove(response_path.c_str());int rc=system((cmd+" &").c_str());if(rc!=0){std::cerr<<"Online controller launch failed at "<<minute<<" rc="<<rc<<"\n";exit(44);}int polls=0,maxpolls=std::max(1,atoi(timeout.c_str())*5);while(!std::ifstream(response_path.c_str()).good()){std::this_thread::sleep_for(std::chrono::milliseconds(200));if(++polls>maxpolls){std::cerr<<"Online response timeout at "<<minute<<"\n";exit(44);}}std::string request_path=run_out+"/runtime_requests/"+rid+"/"+std::to_string(minute)+"/request.json";std::string s=slurp(response_path),q=slurp(request_path);if(s.empty()||q.empty()||s.find("\"schema_valid\": true")==std::string::npos||s.find("\"fallback_used\": false")==std::string::npos||s.find("\"minute\": "+std::to_string(minute))==std::string::npos||s.find("\"seed\": "+std::to_string(expected_seed))==std::string::npos||json_str(s,"run_id")!=rid||json_str(s,"condition")!=condition_name||json_str(s,"input_hash")!=json_str(q,"input_hash")){std::cerr<<"Online response identity/schema validation failed\n";exit(45);}std::set<std::string> agents;for(auto const& x:agent_by_cell)agents.insert(x.second);if(minute==0)remove((run_out+"/agent_action_execution_audit.csv").c_str());std::ofstream audit((run_out+"/agent_action_execution_audit.csv").c_str(),std::ios::app);if(minute==0)audit<<"run_id,seed,condition,minute,agent_id,request_hash,response_hash,oxidative_stress,epithelial_injury,inflammation,immune_recruitment,edema_proxy,death_signal,repair_signal,ecm_remodeling,toxicant_uptake,motility,secretion_multiplier,uptake_multiplier,motility_multiplier,death_tendency,repair_tendency,worker_count,represented_abundance,executed\n";for(auto const& a:agents){size_t p=s.find("\"agent_id\": \""+a+"\"");if(p==std::string::npos){std::cerr<<"Missing Agent response "<<a<<"\n";exit(48);}Policy x;x.oxidative=json_num(s,"executed_oxidative_stress",p);x.injury=json_num(s,"executed_epithelial_injury",p);x.inflammation=json_num(s,"executed_inflammation",p);x.recruitment=json_num(s,"executed_immune_recruitment",p);x.edema=json_num(s,"executed_edema_proxy",p);x.death=json_num(s,"executed_death_signal",p);x.repair=json_num(s,"executed_repair_signal",p);x.ecm=json_num(s,"executed_ecm_remodeling",p);x.uptake=json_num(s,"executed_toxicant_uptake",p);x.motility=json_num(s,"executed_motility",p);policies[a]["online"]=x;secretion_multiplier[a]=json_num(s,"executed_secretion_multiplier",p);uptake_multiplier[a]=json_num(s,"executed_uptake_multiplier",p);motility_multiplier[a]=json_num(s,"executed_motility_multiplier",p);death_tendency[a]=json_num(s,"executed_death_tendency",p);repair_tendency[a]=json_num(s,"executed_repair_tendency",p);abundance_fraction[a]=json_num(s,"abundance_fraction",p);abundance_target[a]=json_str(s,"abundance_target",p);int n=0;double w=0;for(auto c:*all_cells)if(agent_by_cell[c->ID]==a){n++;w+=c->custom_data["represented_abundance"];}audit<<rid<<",NA,"<<condition_name<<","<<minute<<","<<a<<","<<json_str(q,"input_hash")<<","<<file_sha256(response_path)<<","<<x.oxidative<<","<<x.injury<<","<<x.inflammation<<","<<x.recruitment<<","<<x.edema<<","<<x.death<<","<<x.repair<<","<<x.ecm<<","<<x.uptake<<","<<x.motility<<","<<secretion_multiplier[a]<<","<<uptake_multiplier[a]<<","<<motility_multiplier[a]<<","<<death_tendency[a]<<","<<repair_tendency[a]<<","<<n<<","<<w<<",true\n";}apply_abundance_requests();}

void setup_microenvironment(void){initialize_microenvironment();run_out=parameters.strings("run_output");condition_name=parameters.strings("condition");}
void create_cell_types(void){initialize_default_cell_definition();cell_defaults.phenotype.secretion.sync_to_microenvironment(&microenvironment);initialize_cell_definitions_from_pugixml();build_cell_definitions_maps();setup_signal_behavior_dictionaries();setup_cell_rules();for(auto cd:cell_definitions_by_index){cd->phenotype.secretion.sync_to_microenvironment(&microenvironment);cd->functions.update_phenotype=phenotype_function;cd->functions.custom_cell_rule=custom_function;}}
void setup_tissue(void){load_policies();std::ifstream f(parameters.strings("registry_path").c_str());if(!f.good()){std::cerr<<"Missing registry\n";exit(33);}std::string line;std::getline(f,line);while(std::getline(f,line)){auto z=split(line);if(z.size()<6)continue;std::string worker=z[0],agent=z[1],ct=z[2];Cell* c=create_cell(*cell_definitions_by_name[ct]);c->assign_position({atof(z[3].c_str()),atof(z[4].c_str()),0});worker_by_cell[c->ID]=worker;agent_by_cell[c->ID]=agent;double w=atof(z[5].c_str());c->custom_data["represented_abundance"]=w;c->custom_data["base_abundance"]=w;c->custom_data["injury_state"]=0;c->custom_data["inflammation_state"]=0;c->custom_data["repair_state"]=0;c->custom_data["cumulative_exposure"]=0;c->custom_data["damage_memory"]=0;c->custom_data["sustained_injury_duration"]=0;c->custom_data["inflammatory_memory"]=0;c->custom_data["resolution_memory"]=0;c->custom_data["injury_latched"]=0;c->custom_data["previous_toxicant"]=0;c->custom_data["exposure_peak"]=0;c->custom_data["post_exposure"]=0;c->custom_data["stage_code"]=0;c->custom_data["previous_stage_code"]=0;c->custom_data["transition_reason_code"]=7;expected_workers++;}if(expected_workers!=parameters.ints("expected_workers"))exit(35);online_checkpoint(0);initialize_exposure();}
int last_abundance_minute=-1;void update_abundance_due(){int minute=(int)std::floor(PhysiCell_globals.current_time+1e-8);if(minute==last_abundance_minute||!all_cells)return;last_abundance_minute=minute;double epi=0,injbase=0,resbase=0,recbase=0,dmnum=0,imnum=0;for(auto x:*all_cells){std::string a=agent_by_cell[x->ID];double b=x->custom_data["base_abundance"];if(a=="AT1"||a=="AT2"||a=="airway_epithelial"){epi+=b;dmnum+=b*x->custom_data["damage_memory"];}if(a=="injured_Krt8_epithelial")injbase+=b;if(a=="resident_macrophage"){resbase+=b;imnum+=b*x->custom_data["inflammatory_memory"];}if(a=="recruited_monocyte_macrophage")recbase+=b;}double ted=.08*epi*clamp01((dmnum/std::max(epi,1e-12)-.08)/.20),tm=.05*resbase*clamp01((imnum/std::max(resbase,1e-12)-.04)/.20);double sum=0;for(auto x:*all_cells){std::string a=agent_by_cell[x->ID];double b=x->custom_data["base_abundance"],w=b;if(a=="AT1"||a=="AT2"||a=="airway_epithelial")w=b*(1-ted/std::max(epi,1e-12));if(a=="injured_Krt8_epithelial")w=b+ted*b/std::max(injbase,1e-12);if(a=="resident_macrophage")w=b*(1-tm/std::max(resbase,1e-12));if(a=="recruited_monocyte_macrophage")w=b+tm*b/std::max(recbase,1e-12);x->custom_data["represented_abundance"]=std::max(0.0,w);sum+=std::max(0.0,w);}for(auto x:*all_cells)x->custom_data["represented_abundance"]/=sum;}
void phenotype_function(Cell* c,Phenotype& p,double dt){emit_due();int cps[8]={0,30,60,240,480,720,1440,2880};for(int k=0;k<8;k++)if(PhysiCell_globals.current_time+1e-7>=cps[k])online_checkpoint(cps[k]);update_abundance_due();if(c->phenotype.death.dead)return;auto d=c->nearest_density_vector();int tox=density("toxicant_proxy"),ox=density("oxidative_stress"),inj=density("epithelial_injury"),inf=density("inflammation"),ed=density("edema_proxy"),dea=density("death_signal"),rep=density("repair_signal");double lt=d[tox],lo=d[ox],li=d[inj],lf=d[inf];double &ce=c->custom_data["cumulative_exposure"],&dm=c->custom_data["damage_memory"],&dur=c->custom_data["sustained_injury_duration"],&im=c->custom_data["inflammatory_memory"],&rm=c->custom_data["resolution_memory"],&is=c->custom_data["injury_state"],&fs=c->custom_data["inflammation_state"],&rs=c->custom_data["repair_state"],&lat=c->custom_data["injury_latched"],&prev=c->custom_data["previous_toxicant"];
ce=clamp01(ce+dt*(.006*lt-.002*ce));double &peak=c->custom_data["exposure_peak"],&post=c->custom_data["post_exposure"];peak=std::max(peak,ce);if(peak>=.06&&lt<.03&&ce<.8*peak)post=1;double drive=clamp01(.45*ce+.25*lo+.20*li+.10*is);dm=clamp01(dm+dt*(.004*drive-.0006*dm));if(dm>=.08)lat=1;if(dm<.035)lat=0;dur=std::max(0.0,std::min(720.0,dur+dt*((dm>=.06||is>=.04)?1.0:-.5)));im=clamp01(im+dt*(.0025*clamp01((lf+is+dm)/3.0)-.0008*im));if(post>.5&&lt<.03&&dm>=.03)rm=clamp01(rm+dt*(.0015*dm-.0005*rm));else rm=clamp01(rm-dt*.0005*rm);is=clamp01(is+dt*(lat?.004*(dm-is):-.001*is));fs=clamp01(fs+dt*.002*(im-fs));rs=clamp01(rs+dt*.001*(rm-rs));std::string a=agent_by_cell[c->ID],st=stage_name(c,lt);c->custom_data["stage_code"]=st=="early_stress"?0:(st=="injury_accumulating"?1:(st=="inflammatory"?2:3));Policy q=active(a,st);double scale=c->custom_data["represented_abundance"]*expected_workers;bool epi=contains(a,"AT")||contains(a,"epithelial"),immune=contains(a,"macrophage")||contains(a,"monocyte")||contains(a,"neutrophil")||contains(a,"lymphoid"),endo=contains(a,"endothelial"),fib=contains(a,"fibroblast");double early=st=="early_stress",acc=st=="injury_accumulating",infl=st=="inflammatory",res=st=="resolution";
p.secretion.uptake_rates[tox]=.002*q.uptake*uptake_multiplier[a]*scale;p.secretion.secretion_rates[ox]=.020*q.oxidative*secretion_multiplier[a]*(epi||endo?1:.25)*clamp01(lt+ce)*scale;p.secretion.secretion_rates[inj]=.018*q.injury*secretion_multiplier[a]*(epi||endo?1:.15)*clamp01(dm+ce)*scale;p.secretion.secretion_rates[inf]=.016*clamp01(q.inflammation+.5*q.recruitment)*secretion_multiplier[a]*(immune?1:.2)*clamp01(im+is)*scale;p.secretion.secretion_rates[ed]=.012*q.edema*secretion_multiplier[a]*(endo?1:.1)*clamp01(dm+im)*scale;p.secretion.secretion_rates[dea]=.012*q.death*secretion_multiplier[a]*(epi||endo?1:.1)*clamp01(dm+is)*scale;p.secretion.secretion_rates[rep]=.010*clamp01(q.repair+.5*q.ecm)*secretion_multiplier[a]*(fib||contains(a,"AT2")||contains(a,"resident_macrophage")?1:.15)*rm*scale;is=clamp01(is+dt*.0005*death_tendency[a]);rs=clamp01(rs+dt*.0005*repair_tendency[a]);for(int id:{ox,inj,inf,ed,dea,rep})p.secretion.saturation_densities[id]=1.0;c->set_internal_uptake_constants(dt);p.motility.migration_speed=.35*clamp01(q.motility+.5*q.recruitment)*motility_multiplier[a];p.motility.migration_bias=0;prev=lt;}
